    /// <summary>Every compiled door by its name.</summary>
    private static readonly Dictionary<string, DoorDefinition> ByName = Definitions.ToDictionary(door => door.Name);

    /// <summary>The compiled door named <paramref name="name"/>.</summary>
    internal static DoorDefinition Find(string name) => ByName[name];

    /// <summary>Builds the door named <paramref name="name"/> from its fields.</summary>
    private static DoorDefinition Door(string name, RoomDefinition destination, DoorOrientation orientation,
        Position16<RoomBlocks> roomObjectBlock, Position16<RoomScreens> destinationScreen, DoorSamusSpeed samusSpeed,
        DoorSetupCode setupCode) =>
        new(name, destination, orientation, roomObjectBlock, destinationScreen, samusSpeed, setupCode);
    /// <summary>The door into the Landing Site room that demo set 3 uses for its demos 0, 2 and 4.</summary>
    public static DoorDefinition DemoSet3024 { get; } = Find(nameof(DemoSet3024));
    /// <summary>An unused door that no room lists.</summary>
    public static DoorDefinition UnusedNorfairRoom0 { get; } = Find(nameof(UnusedNorfairRoom0));
    /// <summary>An unused third door of the West Sand Hall room.</summary>
    public static DoorDefinition WestSandHallUnlistedThirdDoor { get; } = Find(nameof(WestSandHallUnlistedThirdDoor));
    /// <summary>An unused third door of the East Sand Hall room.</summary>
    public static DoorDefinition EastSandHallUnlistedThirdDoor { get; } = Find(nameof(EastSandHallUnlistedThirdDoor));
